// G5 causal temporal rescoring (Seq-NMS / tubelet score smoothing, online variant).
// EXACT mirror of ml/eval/temporal.py (parity: tests/cvTemporal.test.ts replays
// ml/eval/fixtures/temporal_parity.json generated by the Python side).
//
// Per processed frame, after decode (at a lower pre-threshold) + normalised coords + scene guard,
// before the tracker: link each current box to the best-IoU box (class-agnostic, IoU >= iouLink)
// in each of the last (window - 1) frames, sum scores per class, and divide by the number of
// frames in the window (missing frames count 0). Isolated one-frame boxes fall below minScore;
// boxes seen in most frames keep their score. The class with the highest summed score wins
// (ties -> lowest class id). Causal only; reset() clears the buffer.
import type { Detection } from './tracker.ts';
import type { Box } from './preprocess.ts';

export type TemporalParams = { window: number; iouLink: number; preScore: number; minScore: number };
export const DEFAULT_TEMPORAL: TemporalParams = { window: 5, iouLink: 0.5, preScore: 0.2, minScore: 0.35 };

function iouT(a: Box, b: Box): number {
  const ix = Math.max(0, Math.min(a[2], b[2]) - Math.max(a[0], b[0]));
  const iy = Math.max(0, Math.min(a[3], b[3]) - Math.max(a[1], b[1]));
  const inter = ix * iy;
  const u = (a[2] - a[0]) * (a[3] - a[1]) + (b[2] - b[0]) * (b[3] - b[1]) - inter;
  return u > 0 ? inter / u : 0;
}

export class TemporalRescorer {
  params: TemporalParams;
  buf: Detection[][] = [];

  constructor(params: Partial<TemporalParams> = {}) {
    this.params = { ...DEFAULT_TEMPORAL, ...params };
  }

  reset(): void {
    this.buf = [];
  }

  update(dets: Detection[]): Detection[] {
    const P = this.params;
    const cur = dets.filter((d) => d.score >= P.preScore);
    const frames = this.buf.length + 1;
    const out: Array<Detection & { i: number }> = [];
    cur.forEach((d, idx) => {
      const acc = new Map<number, number>([[d.classId, d.score]]);
      for (const past of this.buf) {
        let best: Detection | null = null;
        let bi = P.iouLink;
        for (const q of past) {
          const v = iouT(d.box, q.box);
          if (v >= bi && (best === null || v > bi)) { best = q; bi = v; }
        }
        if (best !== null) acc.set(best.classId, (acc.get(best.classId) ?? 0) + best.score);
      }
      let c = -1;
      let cs = -Infinity;
      for (const [k, v] of acc) if (v > cs || (v === cs && k < c)) { c = k; cs = v; }
      const s = cs / frames;
      if (s >= P.minScore) out.push({ box: [...d.box] as Box, classId: c, score: s, i: idx });
    });
    this.buf.push(cur.map((d) => ({ box: [...d.box] as Box, classId: d.classId, score: d.score })));
    const keepN = Math.max(0, P.window - 1);
    if (this.buf.length > keepN) this.buf = keepN > 0 ? this.buf.slice(this.buf.length - keepN) : [];
    out.sort((a, b) => b.score - a.score || a.i - b.i);
    return out.map(({ box, classId, score }) => ({ box, classId, score }));
  }
}
